# Try reversed logic: DUPS -> HOLLOW, NO_DUPS -> SOLID
def transform_reversed(input_grid):
    """
    If box has consecutive duplicate rows -> HOLLOW
    If box has NO consecutive duplicate rows -> SOLID
    """
    import collections

    r, c = len(input_grid), len(input_grid[0])
    visited = set()

    def bfs(start_r, start_c):
        comp_coords = [(start_r, start_c)]
        queue = collections.deque([(start_r, start_c)])
        visited.add((start_r, start_c))
        while queue:
            rr, cc = queue.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = rr + dr, cc + dc
                if 0 <= nr < r and 0 <= nc < c and input_grid[nr][nc] == 5 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    comp_coords.append((nr, nc))
                    queue.append((nr, nc))
        return comp_coords

    components = []
    for i in range(r):
        for j in range(c):
            if input_grid[i][j] == 5 and (i,j) not in visited:
                coords = bfs(i, j)
                rmin, rmax = min(x[0] for x in coords), max(x[0] for x in coords)
                cmin, cmax = min(x[1] for x in coords), max(x[1] for x in coords)
                components.append({'coords': coords, 'rmin': rmin, 'rmax': rmax, 'cmin': cmin, 'cmax': cmax})

    output_grid = [[0]*c for _ in range(r)]

    for comp in components:
        rmin, rmax, cmin, cmax = comp['rmin'], comp['rmax'], comp['cmin'], comp['cmax']

        # Check for consecutive duplicate rows in ORIGINAL component pattern
        orig_pattern = []
        for i_row in range(rmin, rmax+1):
            orig_pattern.append([input_grid[i_row][j] for j in range(cmin, cmax+1)])

        has_consecutive_dups = False
        for i in range(len(orig_pattern)-1):
            if orig_pattern[i] == orig_pattern[i+1]:
                has_consecutive_dups = True
                break

        h = rmax - rmin + 1
        w = cmax - cmin + 1

        # Decide: hollow or solid
        if has_consecutive_dups:
            # HOLLOW: boundary only
            for i in range(h):
                for j in range(w):
                    if i == 0 or i == h-1 or j == 0 or j == w-1:
                        output_grid[rmin+i][cmin+j] = 5
        else:
            # SOLID: all cells in bounding box
            for i in range(h):
                for j in range(w):
                    output_grid[rmin+i][cmin+j] = 5

    return output_grid

